// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 100, D: 100.5, E: 0.99, F: 33.33, G: 101, H: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const res = await fetch(`${base}/orders`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ items }),
  })
  return { status: res.status, body: await res.json() }
}

// [label, items, expected total]
const totals = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['sums multiple lines', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 71],
  ['exactly 100 gets NO discount (threshold is strict >)', [{ sku: 'C', qty: 1 }], 100],
  ['100.5 gets 10% off: 90.45 floored to 90', [{ sku: 'D', qty: 1 }], 90],
  ['101 gets 10% off: 90.9 floored to 90 (truncated, not rounded)', [{ sku: 'G', qty: 1 }], 90],
  ['200 -> 180', [{ sku: 'C', qty: 2 }], 180],
  ['large order 10000 -> 9000', [{ sku: 'H', qty: 10 }], 9000],
  ['flat 10% regardless of size (no tiers)', [{ sku: 'H', qty: 100 }], 90000],
  ['fractional total below threshold is floored: 99.99 -> 99', [{ sku: 'E', qty: 101 }], 99],
  ['fractional total: 33.33*4=133.32 -> 119.988 -> 119', [{ sku: 'F', qty: 4 }], 119],
  ['qty 0 contributes nothing', [{ sku: 'A', qty: 0 }], 0],
  ['discount applies to combined total across lines', [{ sku: 'A', qty: 6 }, { sku: 'B', qty: 2 }, { sku: 'E', qty: 1 }], 111.99 * 0 + 100],
]
// the last case sums to 111.99 -> 100.791 -> 100; fix expected below for clarity
totals[totals.length - 1][2] = 100

for (const [label, items, expected] of totals) {
  test(`total: ${label}`, async () => {
    const { status, body } = await post(items)
    assert.equal(status, 201)
    assert.equal(body.total, expected)
    assert.deepEqual(body.items, items)
  })
}

test('order is retrievable with same total', async () => {
  const { body } = await post([{ sku: 'C', qty: 2 }])
  const res = await fetch(`${base}/orders/${body.id}`)
  assert.deepEqual(await res.json(), body)
})

test('unknown order returns 200 with error body (quirk)', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('empty/missing items -> 400', async () => {
  assert.deepEqual(await post([]), { status: 400, body: { error: 'items required' } })
})

test('unknown route -> 404', async () => {
  const res = await fetch(`${base}/nope`)
  assert.equal(res.status, 404)
})
EOF
